export CUDA_VISIBLE_DEVICES=0,1
echo "train_rec_single_dataset_finetuning_base.sh"
# 测试时间 20220831
# 已配置为2个GPU

# Due to the limited number of data samples in the single-dataset setting, MRefM did not yield significant improvements in performance. To streamline the training process and facilitate the reproducibility of our work, we provide a training approach without MRefM pre-training specifically for the single-dataset scenario.

# ========== 路径配置 ==========
DATA_ROOT=/root/shared-nvme/oneref/data/image_data
SPLIT_ROOT=/root/shared-nvme/oneref/data/ref_data_shuffled
BEIT3_CHECKPOINT=/root/shared-nvme/oneref/data/beit3_checkpoint
OUTPUT_DIR=/root/shared-nvme/oneref/output
# ==============================

######## warmup
CUDA_VISIBLE_DEVICES=0,1 python -m torch.distributed.launch --nproc_per_node=2 --master_port 28887 --use_env train_oneref.py --num_workers 4 --epochs 10 --batch_size 16 --lr 0.00025  --lr_scheduler cosine --aug_crop --aug_scale --aug_translate    --imsize 384 --max_query_len 64  --model beit3_base_patch16_384 --task grounding --sentencepiece_model ${BEIT3_CHECKPOINT}/beit3.spm --dataset unc      --use_regress_box  --frozen_backbone          --finetune ${BEIT3_CHECKPOINT}/beit3_base_indomain_patch16_224.pth --data_root ${DATA_ROOT} --split_root ${SPLIT_ROOT}/single_dataset  --output_dir ${OUTPUT_DIR}/v001/unc;
